import { useCallback, useEffect, useMemo, useState } from 'react';
import { apiGet, apiPost } from '@/lib/axios/axios-utils';
import { endpoints } from '@/lib/axios/axios-global';
import { toast } from 'sonner';
import {
    INTERVIEW_EVALUATION_CRITERIA,
    averageEvaluationPercent,
} from '../constants/interviewEvaluation';
import type { Interview, InterviewEvaluationScores } from '../types/interview.types';

function buildScoresFromDetail(evaluation: InterviewEvaluationScores | null | undefined): Record<string, number> {
    const ev = evaluation ?? {};
    const out: Record<string, number> = {};
    for (const { key } of INTERVIEW_EVALUATION_CRITERIA) {
        const raw = ev[key as keyof InterviewEvaluationScores];
        out[key] = typeof raw === 'number' && !Number.isNaN(raw) ? raw : 0;
    }
    return out;
}

function scoresToPayload(scores: Record<string, number>): InterviewEvaluationScores {
    const out: InterviewEvaluationScores = {};
    for (const { key } of INTERVIEW_EVALUATION_CRITERIA) {
        const v = scores[key];
        (out as Record<string, number>)[key] = typeof v === 'number' && !Number.isNaN(v) ? v : 0;
    }
    return out;
}

function resolveLoadUrl(interview: Interview | null): string | null {
    if (!interview) return null;
    if (interview.fromKanban) {
        const aid = interview.career_applicant_id ?? interview.applicant?.id;
        if (aid == null) return null;
        return `${endpoints.interview.byApplicant}${aid}`;
    }
    return `${endpoints.interview.show}${interview.id}`;
}

export function useInterviewEvaluationEditor(interview: Interview | null, open: boolean) {
    const [detail, setDetail] = useState<Interview | null>(null);
    const [scores, setScores] = useState<Record<string, number>>({});
    const [notes, setNotes] = useState('');
    const [loading, setLoading] = useState(false);
    const [saving, setSaving] = useState(false);

    useEffect(() => {
        if (!interview) {
            setDetail(null);
            setScores({});
            setNotes('');
            return;
        }

        if (!open) {
            return;
        }

        const url = resolveLoadUrl(interview);
        if (!url) {
            setDetail(null);
            return;
        }

        let cancelled = false;
        setLoading(true);

        void (async () => {
            try {
                const res = await apiGet({ endpoint: url });
                const payload = res.data?.data as Interview | null;
                if (cancelled) return;
                setDetail(payload ?? null);
                if (payload) {
                    setScores(buildScoresFromDetail(payload.evaluation ?? undefined));
                    setNotes(payload.notes ?? '');
                }
            } catch {
                if (!cancelled) {
                    setDetail(null);
                    toast.error('تعذر تحميل بيانات المقابلة');
                }
            } finally {
                if (!cancelled) setLoading(false);
            }
        })();

        return () => {
            cancelled = true;
        };
    }, [open, interview?.id, interview?.fromKanban, interview?.career_applicant_id]);

    const overallPercent = useMemo(
        () => averageEvaluationPercent(scoresToPayload(scores)),
        [scores],
    );

    const updateScore = useCallback((key: string, value: number) => {
        setScores((prev) => ({ ...prev, [key]: value }));
    }, []);

    const save = useCallback(async (): Promise<boolean> => {
        const id = detail?.id;
        if (id == null) return false;
        setSaving(true);
        try {
            await apiPost({
                endpoint: `${endpoints.interview.update}${id}`,
                body: {
                    notes,
                    evaluation: scoresToPayload(scores),
                },
            });
            toast.success('تم حفظ التقييم');
            const res = await apiGet({ endpoint: `${endpoints.interview.show}${id}` });
            const payload = res.data?.data as Interview | null;
            if (payload) {
                setDetail(payload);
                setScores(buildScoresFromDetail(payload.evaluation ?? undefined));
                setNotes(payload.notes ?? '');
            }
            return true;
        } catch (e: unknown) {
            let msg = 'تعذر حفظ التقييم';
            if (e && typeof e === 'object' && 'response' in e) {
                const ax = e as { response?: { data?: { msg?: string } } };
                msg = ax.response?.data?.msg || msg;
            }
            toast.error(msg);
            return false;
        } finally {
            setSaving(false);
        }
    }, [detail?.id, notes, scores]);

    return {
        detail,
        scores,
        notes,
        setNotes,
        updateScore,
        loading,
        saving,
        save,
        overallPercent,
        criteria: INTERVIEW_EVALUATION_CRITERIA,
    };
}
