import { PrimaryButton } from '@/components/buttons/PrimaryButton';
import {
    Interview,
    interviewApplicantName,
    interviewJobTitle,
} from '../../types/interview.types';
import { Dialog, DialogContent, DialogHeader, DialogTitle } from '@/components/ui/dialog';
import { useEffect, useState } from 'react';
import { apiPost } from '@/lib/axios/axios-utils';
import { endpoints } from '@/lib/axios/axios-global';
import { toast } from 'sonner';

interface InterviewRejectionProps {
    interview: Interview | null;
    /** `career_interviews.id` — required for API; falls back to `interview.id` when list row */
    interviewRecordId?: number | null;
    openRejectionDialog: boolean;
    setopenRejectionDialog: (open: boolean) => void;
    /** Called after successful send so parent can refresh list */
    onSent?: () => void;
}

export default function InterviewRejection({
    interview,
    interviewRecordId,
    openRejectionDialog,
    setopenRejectionDialog,
    onSent,
}: InterviewRejectionProps) {
    const [email, setEmail] = useState('');
    const [message, setMessage] = useState('');
    const [sending, setSending] = useState(false);

    const recordId = interviewRecordId ?? interview?.id;

    useEffect(() => {
        if (openRejectionDialog) {
            setEmail('');
            setMessage('');
        }
    }, [openRejectionDialog, interview?.id, interviewRecordId]);

    const handleSend = async () => {
        if (recordId == null) {
            toast.error('معرّف المقابلة غير متوفر');
            return;
        }
        const trimmedEmail = email.trim();
        if (!trimmedEmail) {
            toast.error('يرجى إدخال البريد الإلكتروني');
            return;
        }
        const trimmedMessage = message.trim();
        if (!trimmedMessage) {
            toast.error('يرجى إدخال نص الرسالة');
            return;
        }

        setSending(true);
        try {
            await apiPost({
                endpoint: `${endpoints.interview.rejectionNotify}${recordId}`,
                body: {
                    email: trimmedEmail,
                    message: trimmedMessage,
                },
            });
            toast.success('تم إرسال البريد وحفظ حالة الرفض');
            setopenRejectionDialog(false);
            onSent?.();
        } catch (e: unknown) {
            let msg = 'تعذر إرسال البريد';
            if (e && typeof e === 'object' && 'response' in e) {
                const ax = e as { response?: { data?: { msg?: string } } };
                msg = ax.response?.data?.msg || msg;
            }
            toast.error(msg);
        } finally {
            setSending(false);
        }
    };

    const name = interviewApplicantName(interview);
    const jobTitle = interviewJobTitle(interview);

    return (
        <div>
            <Dialog open={openRejectionDialog} onOpenChange={setopenRejectionDialog}>
                <DialogContent
                    dir="rtl"
                    showCloseButton={false}
                    className="max-w-[760px] rounded-xl border border-[#E8E7EA] bg-white-blue-50 p-4 sm:p-5 max-h-[90vh] overflow-y-auto"
                >
                    <DialogHeader className="space-y-2">
                        <DialogTitle className="text-right text-[22px] sm:text-[26px] font-semibold leading-[32px] sm:leading-[36px] text-[#E03131]">
                            رسالة الرفض
                        </DialogTitle>
                        <div className="w-full border-b border-[#E8E7EA]" />
                    </DialogHeader>

                    <div className="mt-4 rounded-xl border border-[#E5E7EB] bg-white p-3 shadow-[0px_1px_2px_0px_#1018280D]">
                        <div className="flex items-start justify-between gap-3">
                            <div className="text-right">
                                <h3 className="text-base sm:text-lg font-semibold leading-[26px] text-primery-blue-900">
                                    {name}
                                </h3>
                                <p className="text-sm sm:text-[15px] text-[#625E74]">{jobTitle}</p>
                            </div>
                            <span className="rounded-md bg-[#EDF8F2] px-2 py-0.5 text-[11px] text-[#1D9D62]">
                                مقابلة
                            </span>
                        </div>
                    </div>

                    <div className="mt-6">
                        <label className="mb-1.5 block text-right text-lg sm:text-xl font-semibold leading-[30px] text-primery-blue-900">
                            البريد الالكتروني
                        </label>
                        <input
                            type="email"
                            value={email}
                            onChange={(e) => setEmail(e.target.value)}
                            placeholder="ادخل البريد الالكتروني"
                            autoComplete="email"
                            className="h-[44px] w-full rounded-lg border border-[#E8E7EA] bg-white px-3.5 text-right text-sm text-[#625E74] outline-none placeholder:text-[#CACACA]"
                        />
                    </div>

                    <div className="mt-6">
                        <label className="mb-1.5 block text-right text-lg sm:text-xl font-semibold leading-[30px] text-primery-blue-900">
                            ملاحظات
                        </label>
                        <textarea
                            value={message}
                            onChange={(e) => setMessage(e.target.value)}
                            placeholder="اكتب ملاحظات عن المتقدم"
                            className="h-[130px] w-full resize-none rounded-lg border border-[#E8E7EA] bg-white p-3.5 text-right text-sm text-[#625E74] outline-none placeholder:text-[#CACACA]"
                        />
                    </div>

                    <div className="mt-6 grid grid-cols-1 gap-3 sm:grid-cols-2">
                        <PrimaryButton
                            type="button"
                            disabled={sending || recordId == null}
                            onClick={() => void handleSend()}
                            className="h-[44px] bg-[#FBE2E2] text-[#C52E2E] hover:bg-[#f4d2d2] text-sm sm:text-base font-medium"
                        >
                            {sending ? 'جاري الإرسال...' : 'ارسال عبر البريد'}
                        </PrimaryButton>
                        <PrimaryButton
                            type="button"
                            onClick={() => setopenRejectionDialog(false)}
                            className="h-[44px] border border-[#D0D5DD] bg-transparent text-[#625E74] hover:bg-[#F3F4F6] text-sm sm:text-base font-medium"
                        >
                            إلغاء
                        </PrimaryButton>
                    </div>
                </DialogContent>
            </Dialog>
        </div>
    );
}
